package config

import (
	api "{{.Module}}/sandbox/api"
)

// NewConfig builds Sandbox.Config out of what <ProjectName>Config/project.yaml
// declared when this file was rendered, so nothing has to parse that file to
// know which project it is running as.
// Generated by `{{.GeneratorName}} build` — do not edit by hand.
func NewConfig(sandbox *api.Sandbox) api.Config {
	return api.Config{
		ProjectName: "{{.ProjectName}}",
		Version:     "{{.Version}}",
	}
}
